// PRIMARY: beacon_node/execution_layer/src/block_hash.rs:calculate_execution_block_hash (lines 17-62)
// NOTE: In Lighthouse (consensus client), the Python execution-spec functions _prepare_trie,
// encode_node, Account, and get_storage_root do NOT exist directly. Lighthouse does not compute
// the state account trie — the state_root is delegated to the execution layer (EL) client and
// passed through in ExecutionPayloadRef. Lighthouse only computes transaction and withdrawal
// trie roots using ordered_trie_root. The closest analog for _prepare_trie Account routing is:

pub fn calculate_execution_block_hash<E: EthSpec>(
    payload: ExecutionPayloadRef<E>,
    parent_beacon_block_root: Option<Hash256>,
    execution_requests: Option<&ExecutionRequests<E>>,
) -> (ExecutionBlockHash, Hash256) {
    // Calculate the transactions root.
    // We're currently using a deprecated Parity library for this. We should move to a
    // better alternative when one appears, possibly following Reth.
    let rlp_transactions_root = ordered_trie_root::<KeccakHasher, _>(
        payload.transactions().iter().map(|txn_bytes| &**txn_bytes),
    );

    // Calculate withdrawals root (post-Capella).
    let rlp_withdrawals_root = if let Ok(withdrawals) = payload.withdrawals() {
        Some(ordered_trie_root::<KeccakHasher, _>(
            withdrawals
                .iter()
                .map(|withdrawal| rlp_encode_withdrawal(&JsonWithdrawal::from(withdrawal.clone()))),
        ))
    } else {
        None
    };
    ...
    // Construct the block header (state_root passed through from EL without Lighthouse computing it)
    let exec_block_header = ExecutionBlockHeader::from_payload(
        payload, ..., rlp_transactions_root, rlp_withdrawals_root, ...
    );
}

