// Calculate transactions root (via internal Patricia trie key encoding):
let rlp_transactions_root = ordered_trie_root::<KeccakHasher, _>(
    payload.transactions().iter().map(|txn_bytes| &**txn_bytes),
);
// Key encoding: index i is RLP-encoded as the trie key at position i.
// ordered_trie_root uses sequential integer keys [0, 1, 2, ...] which are RLP encoded.
// The 'patricialize' equivalent in triehash constructs the key from level=0 (full RLP key).
//
// For the withdrawals root (same structure):
let rlp_withdrawals_root = ordered_trie_root::<KeccakHasher, _>(
    withdrawals.iter()
        .map(|w| rlp_encode_withdrawal(&JsonWithdrawal::from(w.clone()))),
);

