// PRIMARY: beacon_node/execution_layer/src/engine_api/json_structures.rs:EncodableJsonWithdrawal (lines 676-693)
// Lighthouse's analog for Address(preimage) conversion in _prepare_trie.
// The address is converted to &[u8] slice for RLP encoding — preserving all 20 bytes.

#[derive(Debug, PartialEq, Clone, RlpEncodable)]
pub struct EncodableJsonWithdrawal<'a> {
    pub index: u64,
    pub validator_index: u64,
    pub address: &'a [u8],  // 20-byte address as raw byte slice
    pub amount: u64,
}

impl<'a> From<&'a JsonWithdrawal> for EncodableJsonWithdrawal<'a> {
    fn from(json_withdrawal: &'a JsonWithdrawal) -> Self {
        Self {
            index: json_withdrawal.index,
            validator_index: json_withdrawal.validator_index,
            address: json_withdrawal.address.as_slice(),  // Address -> &[u8] (20 bytes)
            amount: json_withdrawal.amount,
        }
    }
}

// CALLER: beacon_node/execution_layer/src/block_hash.rs:rlp_encode_withdrawal (lines 64-69)
pub fn rlp_encode_withdrawal(withdrawal: &JsonWithdrawal) -> Vec<u8> {
    let mut out: Vec<u8> = vec![];
    EncodableJsonWithdrawal::from(withdrawal).encode(&mut out);
    out
}

